import json
from pathlib import Path
W=Path(__file__).resolve().parent
quizzes={
'ad-patchcore':['正常庫與節拍怎麼取捨？','新批次的允收紋理較多；小代表庫會誤報，較大的候選庫已改善誤報，但查詢時間超出你的節拍預算。','你會調整代表子集、保留大庫做離線覆核，或改測另一方法？先說出不能犧牲的條件。','三條路都可能合理。若線上節拍優先，先用涵蓋新正常變化的子集重測誤報與漏檢；若允許離線覆核，可保留大庫並計入等待成本。若仍不符合節拍，再比較其他方法的完整成本。已確認正常才可納入參考，所有候選都要用相同獨立正常／缺陷資料驗證。'],
'ad-padim':['固定位置，還是放寬取像？','治具更換後板子會小幅旋轉。你可以增加對位步驟，也可以維持自由取像並比較查找式正常參考。','保留PaDiM加對位，或比較PatchCore／AnomalyDINO？哪種現場條件會讓你改選？','若幾何可穩定對位且新增耗時可接受，保留PaDiM並重估位置分布合理。若遮擋或姿態使對位不可靠，可比較查找式參考，但它們也不保證旋轉不變。用同批影像量對位失敗、誤報、漏檢與總耗時；不能把位置錯配一律當正常變化吸收。'],
'ad-anomalydino':['少樣本先做哪一步？','新產品只有少量確認正常影像，舊DINOv2特徵可用；一週內只能優先做補拍正常變化，或進行模型微調試驗。','你先補拍並建立參考，還是先微調？什麼結果會支持下一步換路線？','若問題是光照、批次或姿態覆蓋不足，先補正常參考通常更直接，也符合本方法免額外微調的起點。若獨立檢查顯示特徵無法分開任務關心的差異，再考慮微調或其他方法；那是新增方案，需另設訓練與驗證。少樣本與免微調都不代表免測誤報漏檢。'],
'ad-efficientad':['保留兩路，還是拆開檢查？','產線同時要查表面污點與漏裝。完整EfficientAD候選的兩類驗證尚未齊全；另一方案是局部檢查加獨立的裝配規則。','先補完整方法的兩類測試，或把表面與裝配分開？如何比較兩方案？','若希望共用一套異常流程，先補正常變化、污點、漏裝與錯位資料，檢查兩路校準。若裝配幾何固定且規則可清楚驗證，分開檢查也合理，但要計入兩套流程的誤報、漏檢、延遲和維護。不能拿污點通過的證據代替漏裝驗證。'],
'resnet':['資料還是深度先投入？','新背景讓原ResNet分類變差。你可以先擴充跨背景標註，也可以比較更深的ResNet；同時做兩者會超出本輪時間。','你如何用一個小檢查決定先投入哪一邊？','先用同工件、不同背景的保留資料找錯誤集中在哪裡。若背景切換主導錯誤，先改善資料與取像較直接；若跨背景仍有一致的細部類別混淆，可比較容量或解析度。更深網路可能有用，但殘差不自動消除背景捷徑，仍須同資料驗證。'],
'convnext':['值得換掉穩定基準嗎？','ResNet已符合現行需求；ConvNeXt候選在困難類別較好，但部署記憶體較高，且需要重新驗證。','你會維持ResNet、全面換成ConvNeXt，或只讓困難樣本走新模型？要補哪些成本證據？','若困難類別的漏分成本足以抵銷資源與驗證成本，可以換；若收益很小，保留穩定基準合理。分流方案也可測，但要驗證分流漏接、兩模型維護及最壞延遲。同資料、硬體、輸入和門檻比較，不能只按模型年代決定。'],
'vit-classifier':['分流還是輪廓？','ViT分類可以把可疑工件送人覆核。另一部門希望直接取得缺陷輪廓，但像素標註成本高。','先交付分類覆核流程，或增加分割任務？哪些需求會改變你的決定？','若工作目的是先分流且人工覆核量可接受，可先交付經驗證的分類流程；若後段確實需要輪廓或定位，則要定義相應輸出與標註並驗證。注意力圖不能替代輪廓真值。比較時一起計入標註、覆核、漏分和後段量測校正成本。'],
'u-net':['保細縫，還是保節拍？','完整高解析度影像能保留細焊縫，但耗時較長；切圖可聚焦局部，卻會失去部分上下文並增加拼接邊界。','你先測高解析度整圖，還是重疊切圖？驗收不能只看哪個指標？','兩者都值得用相同保留影像比較。整體形狀很重要時先保留上下文；局部細線主導且可處理拼接時可試重疊切圖。除區域重疊外，另看細線召回、斷裂、邊界偏移與完整耗時。要交毫米尺寸仍需尺度與透視校正。'],
'segformer':['語意區域能不能先計數？','現場多數墊圈彼此分開，少數會相接。現有語意遮罩已可用，改實例分割需要新增逐件標註。','先用語意遮罩加連通區與人工例外，或直接建實例分割？說明可接受條件。','若能保證分離條件並可靠識別例外，語意遮罩加連通區可作受限方案，需驗證相接件漏計與覆核量。若必須普遍處理相接、遮擋或逐件ID，應比較實例輸出及標註成本。换SegFormer骨幹本身不會把語意類別變成實例ID。'],
'yolo-seg':['補模型資料，還是改分料？','兩個相接墊圈常只被算成一件。可增加重疊標註訓練，也可用分料或調整視角讓兩件更容易看清。','你會先做哪一項小試驗？何時保留兩者一起做？','先檢查人是否能從原圖穩定分辨兩件。可見線索足夠而資料不足時先補重疊樣本；遮擋讓身份難辨時改善分料／視角更直接。兩者都有問題可合用，但各自量成本與效益。驗證逐件召回、錯誤合併／切分、計數誤差和節拍，面積估數只能作另行驗證的受限方案。'],
'keypoint-r-cnn':['先交2D，還是接3D？','目前工站只需檢查孔中心是否落在影像允收區；未來另一工站想用相機姿態做對位。','這輪先交2D點核對，或同時建立3D流程？各自還缺哪些資料？','目前需求可先交逐件2D點與允收核對，驗證點名、遮擋與映回原圖誤差。若本輪已需3D接手，才同時準備足夠正確2D–3D對應、已知幾何、相機校正、多解檢查及必要外參。不能把2D分數當姿態精度，也不必為尚未需要的輸出先付全部成本。'],
'pose':['加標記，還是多一個視角？','接近對稱的四孔板缺口被遮住，兩個候選姿態都可能有小重投影誤差。工件表面可能不允許永久標記。','選可移除標記、調整視角，或保留人工覆核？你要先核對哪個限制？','先核對表面處理規範、可見性、節拍和校正條件。可移除且穩定可見的標記可提供點身分；若不能標記，可測額外視角，但須維護校正與遮擋條件。短期人工覆核也可能合理，需明確攔下不確定解。任何路線都要驗證物理姿態，不能只選重投影分數略低者。']
}
def apply(data):
 for slug,q in quizzes.items():data[slug]['quiz']=q
 mapping=str.maketrans({'没':'沒','确':'確','换':'換','现':'現','两':'兩','个':'個','点':'點','体':'體','态':'態','够':'夠','线':'線','层':'層','读':'讀','对':'對','后':'後','说':'說','这':'這','问':'問','验':'驗','样':'樣','标':'標','从':'從','图':'圖','输':'輸','应':'應','与':'與','进':'進'})
 def clean(x):
  if isinstance(x,str):return x.translate(mapping)
  if isinstance(x,list):return [clean(v) for v in x]
  if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
  return x
 return clean(data)
if __name__=='__main__':
 p=W/'lesson-content.json';p.write_text(json.dumps(apply(json.loads(p.read_text(encoding='utf-8'))),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print('12 conditional trade-off quizzes authored')
